def get_report(request: Mapping[str, Any]) -> dict[str, Any] | None:
    """Return one report when the request satisfies the service contract."""
    records = load_reports()

    report_id = request.get("report_id")
    record = records.get(report_id)
    if record is None:
        return None

    user_id = request.get("user_id")
    role = request.get("role")
    owner_id = record.get("owner_id")
    visibility = record.get("visibility")

    if visibility == "internal":
        if role == "admin":
            return record
        raise AccessDenied("only admins may read internal reports")

    if visibility == "public":
        if user_id is not None and user_id == owner_id:
            return record
        raise AccessDenied("only the owner may read a public report")

    raise AccessDenied("report is not readable")
